    void *ptr;

    if (!atomic_pool_initialized) {
        pr_warn("Attempt to allocate from uninitialized atomic pool.\n");
        return NULL;
    }

    ptr = kmalloc(size, flags);
    if (!ptr)
        return NULL;

    *ret_page = virt_to_page(ptr);
    memset(ptr, 0, size);

    return ptr;
}

